// PROCESAR TOKENS - BÚSQUEDA RECURSIVA DINÁMICA
const executionsData = $input.all();
const tokenAnalysis = [];

console.log('=== PROCESANDO TOKENS ===');
console.log('Total ejecuciones recibidas:', executionsData.length);

// Función recursiva para buscar tokenUsage en cualquier nivel
function findTokenUsage(obj, path = '') {
  const results = [];

  if (!obj || typeof obj !== 'object') return results;

  // Si encontramos tokenUsage directamente
  if (obj.tokenUsage && obj.tokenUsage.totalTokens !== undefined) {
    results.push({
      tokenUsage: obj.tokenUsage,
      path: path
    });
  }

  // Buscar recursivamente en todas las propiedades
  for (const key in obj) {
    if (obj.hasOwnProperty(key)) {
      const newPath = path ? `${path}.${key}` : key;

      if (Array.isArray(obj[key])) {
        // Si es array, buscar en cada elemento
        obj[key].forEach((item, index) => {
          const arrayResults = findTokenUsage(item, `${newPath}[${index}]`);
          results.push(...arrayResults);
        });
      } else if (typeof obj[key] === 'object' && obj[key] !== null) {
        // Si es objeto, buscar recursivamente
        const nestedResults = findTokenUsage(obj[key], newPath);
        results.push(...nestedResults);
      }
    }
  }

  return results;
}

// Función para buscar información de usuario en el trigger
function findUserInfo(runData) {
  let userInfo = {
    wa_id: null,
    name: null
  };

  // Buscar en todos los nodos que puedan ser triggers
  for (const nodeName in runData) {
    if (!nodeName.toLowerCase().includes('trigger') && 
        !nodeName.toLowerCase().includes('whatsapp')) continue;

    const nodeData = runData[nodeName];
    if (!nodeData || nodeData.length === 0) continue;

    // Buscar recursivamente contacts[0].wa_id y contacts[0].profile.name
    function searchContacts(obj) {
      if (!obj || typeof obj !== 'object') return null;

      // Si encontramos contacts array
      if (obj.contacts && Array.isArray(obj.contacts) && obj.contacts[0]) {
        const contact = obj.contacts[0];
        return {
          wa_id: contact.wa_id,
          name: contact.profile?.name || contact.name || 'Usuario Desconocido'
        };
      }

      // Buscar en propiedades anidadas
      for (const key in obj) {
        if (typeof obj[key] === 'object') {
          const result = searchContacts(obj[key]);
          if (result) return result;
        }
      }

      return null;
    }

    const found = searchContacts(nodeData);
    if (found && found.wa_id) {
      userInfo = found;
      console.log(`✅ Usuario encontrado en nodo "${nodeName}":`, userInfo.name, userInfo.wa_id);
      break;
    }
  }

  return userInfo;
}

for (const execution of executionsData) {
  try {
    const executionData = execution.json.data;
    const workflowData = execution.json.workflowData;
    const runData = executionData?.resultData?.runData;

    if (!runData) {
      console.log('❌ Sin runData:', execution.json.id);
      continue;
    }

    console.log('\n🔍 ========================================');
    console.log('Procesando ejecución:', execution.json.id);
    console.log('Workflow:', execution.json.workflowData?.name);
    console.log('Fecha:', execution.json.startedAt);
    console.log('Nodos en ejecución:', Object.keys(runData).length);
    console.log('========================================');

    const executionInfo = {
      executionId: execution.json.id,
      workflowId: execution.json.workflowId,
      workflowName: workflowData?.name || 'Unknown',
      startedAt: execution.json.startedAt,
      stoppedAt: execution.json.stoppedAt,
      duration: new Date(execution.json.stoppedAt) - new Date(execution.json.startedAt),
      totalTokens: 0,
      promptTokens: 0,
      completionTokens: 0,
      geminiNodes: [],
      userPhone: null,
      userName: null
    };

    // 1. BUSCAR USUARIO
    const userInfo = findUserInfo(runData);
    executionInfo.userPhone = userInfo.wa_id;
    executionInfo.userName = userInfo.name;

    // 2. BUSCAR TOKENS EN TODA LA ESTRUCTURA
    let totalTokensFound = 0;

    for (const nodeName in runData) {
      const nodeData = runData[nodeName];

      if (!nodeData || nodeData.length === 0) continue;

      console.log(`\n📦 Analizando nodo: "${nodeName}"`);

      // Buscar tokenUsage recursivamente en TODO el nodo
      const tokenResults = findTokenUsage(nodeData);

      if (tokenResults.length > 0) {
        console.log(`   ✅ Encontrados ${tokenResults.length} registros de tokens`);

        for (const result of tokenResults) {
          const tokenUsage = result.tokenUsage;

          console.log(`   💎 Path: ${result.path}`);
          console.log(`   📊 Tokens:`, {
            total: tokenUsage.totalTokens,
            prompt: tokenUsage.promptTokens,
            completion: tokenUsage.completionTokens
          });

          executionInfo.totalTokens += tokenUsage.totalTokens || 0;
          executionInfo.promptTokens += tokenUsage.promptTokens || 0;
          executionInfo.completionTokens += tokenUsage.completionTokens || 0;
          totalTokensFound++;

          // Guardar info del nodo (evitar duplicados)
          const existingNode = executionInfo.geminiNodes.find(n => n.nodeName === nodeName);
          if (existingNode) {
            existingNode.totalTokens += tokenUsage.totalTokens || 0;
            existingNode.promptTokens += tokenUsage.promptTokens || 0;
            existingNode.completionTokens += tokenUsage.completionTokens || 0;
          } else {
            executionInfo.geminiNodes.push({
              nodeName: nodeName,
              totalTokens: tokenUsage.totalTokens || 0,
              promptTokens: tokenUsage.promptTokens || 0,
              completionTokens: tokenUsage.completionTokens || 0
            });
          }
        }
      }
    }

    // 3. AGREGAR SI HAY TOKENS
    if (executionInfo.totalTokens > 0) {
      tokenAnalysis.push(executionInfo);
      console.log('\n✅ ========================================');
      console.log('EJECUCIÓN AGREGADA');
      console.log('ID:', executionInfo.executionId);
      console.log('Usuario:', executionInfo.userName || 'No identificado');
      console.log('Teléfono:', executionInfo.userPhone || 'N/A');
      console.log('Total Tokens:', executionInfo.totalTokens);
      console.log('  - Prompt:', executionInfo.promptTokens);
      console.log('  - Completion:', executionInfo.completionTokens);
      console.log('Nodos Gemini:', executionInfo.geminiNodes.map(n => n.nodeName).join(', '));
      console.log('========================================');
    } else {
      console.log('\n⚠️ Ejecución sin tokens:', executionInfo.executionId);
    }

  } catch (error) {
    console.log('❌ Error procesando ejecución:', execution.json?.id);
    console.log('Error:', error.message);
    console.log('Stack:', error.stack);
  }
}

console.log('\n\n🎯 ========================================');
console.log('RESUMEN FINAL');
console.log('========================================');
console.log('Total ejecuciones procesadas:', executionsData.length);
console.log('Ejecuciones CON tokens:', tokenAnalysis.length);
console.log('Total tokens acumulados:', tokenAnalysis.reduce((sum, e) => sum + e.totalTokens, 0));
console.log('Total prompt tokens:', tokenAnalysis.reduce((sum, e) => sum + e.promptTokens, 0));
console.log('Total completion tokens:', tokenAnalysis.reduce((sum, e) => sum + e.completionTokens, 0));
console.log('Usuarios únicos:', new Set(tokenAnalysis.map(e => e.userPhone).filter(Boolean)).size);
console.log('========================================\n');

// Ordenar por fecha
tokenAnalysis.sort((a, b) => new Date(a.startedAt) - new Date(b.startedAt));

return tokenAnalysis.map(item => ({ json: item }));

const allData = $input.all();

console.log('=== GENERAR ESTADÍSTICAS ===');
console.log('Total items:', allData.length);

if (!allData || allData.length === 0) {
  return [{
    json: {
      error: 'No hay datos de tokens',
      totalStats: { totalTokens: 0, totalExecutions: 0, uniqueUsers: 0 },
      byDate: [],
      byUser: [],
      byWorkflow: [],
      byHour: []
    }
  }];
}

const byDate = {};
const byUser = {};
const byWorkflow = {};
const byHour = {};

for (const item of allData) {
  const data = item.json;

  if (!data.startedAt || !data.totalTokens) continue;

  const date = new Date(data.startedAt);
  const dateKey = date.toISOString().split('T')[0];
  const hour = date.getHours();

  // Por fecha
  if (!byDate[dateKey]) {
    byDate[dateKey] = { date: dateKey, totalTokens: 0, promptTokens: 0, completionTokens: 0, executionCount: 0 };
  }
  byDate[dateKey].totalTokens += data.totalTokens;
  byDate[dateKey].promptTokens += data.promptTokens;
  byDate[dateKey].completionTokens += data.completionTokens;
  byDate[dateKey].executionCount++;

  // Por hora
  const hourKey = `${dateKey} ${hour.toString().padStart(2, '0')}:00`;
  if (!byHour[hourKey]) {
    byHour[hourKey] = { datetime: hourKey, totalTokens: 0, executionCount: 0 };
  }
  byHour[hourKey].totalTokens += data.totalTokens;
  byHour[hourKey].executionCount++;

  // Por usuario
  if (data.userPhone) {
    if (!byUser[data.userPhone]) {
      byUser[data.userPhone] = {
        phone: data.userPhone,
        name: data.userName,
        totalTokens: 0,
        promptTokens: 0,
        completionTokens: 0,
        executionCount: 0,
        workflows: {}
      };
    }
    byUser[data.userPhone].totalTokens += data.totalTokens;
    byUser[data.userPhone].promptTokens += data.promptTokens;
    byUser[data.userPhone].completionTokens += data.completionTokens;
    byUser[data.userPhone].executionCount++;

    if (!byUser[data.userPhone].workflows[data.workflowName]) {
      byUser[data.userPhone].workflows[data.workflowName] = { name: data.workflowName, tokens: 0, count: 0 };
    }
    byUser[data.userPhone].workflows[data.workflowName].tokens += data.totalTokens;
    byUser[data.userPhone].workflows[data.workflowName].count++;
  }

  // Por workflow
  if (!byWorkflow[data.workflowName]) {
    byWorkflow[data.workflowName] = { name: data.workflowName, totalTokens: 0, promptTokens: 0, completionTokens: 0, executionCount: 0 };
  }
  byWorkflow[data.workflowName].totalTokens += data.totalTokens;
  byWorkflow[data.workflowName].promptTokens += data.promptTokens;
  byWorkflow[data.workflowName].completionTokens += data.completionTokens;
  byWorkflow[data.workflowName].executionCount++;
}

const dateStats = Object.values(byDate).sort((a, b) => a.date.localeCompare(b.date));
const hourStats = Object.values(byHour).sort((a, b) => a.datetime.localeCompare(b.datetime));
const userStats = Object.values(byUser)
  .map(u => ({ ...u, workflows: Object.values(u.workflows) }))
  .sort((a, b) => b.totalTokens - a.totalTokens);
const workflowStats = Object.values(byWorkflow).sort((a, b) => b.totalTokens - a.totalTokens);

const totalStats = {
  totalTokens: allData.reduce((sum, item) => sum + item.json.totalTokens, 0),
  promptTokens: allData.reduce((sum, item) => sum + item.json.promptTokens, 0),
  completionTokens: allData.reduce((sum, item) => sum + item.json.completionTokens, 0),
  totalExecutions: allData.length,
  uniqueUsers: Object.keys(byUser).length,
  dateRange: {
    start: dateStats[0]?.date || null,
    end: dateStats[dateStats.length - 1]?.date || null
  }
};

return [{
  json: {
    totalStats,
    byDate: dateStats,
    byHour: hourStats,
    byUser: userStats,
    byWorkflow: workflowStats
  }
}];
